use std::collections::HashMap;
use std::fmt;
use std::io;
use std::num::ParseFloatError;
use std::rc::Rc;

/*
  Types
*/

#[derive(Clone)]
enum RispExp {
    Bool(bool),
    Symbol(String),
    Number(f64),
    List(Vec&lt;RispExp&gt;),
    Func(fn(&amp;[RispExp]) -&gt; Result&lt;RispExp, RispErr&gt;),
    Lambda(RispLambda),
}

#[derive(Clone)]
struct RispLambda {
    params_exp: Rc&lt;RispExp&gt;,
    body_exp: Rc&lt;RispExp&gt;,
}

impl fmt::Display for RispExp {
    fn fmt(&amp;self, f: &amp;mut fmt::Formatter) -&gt; fmt::Result {
        let str = match self {
            RispExp::Bool(a) =&gt; a.to_string(),
            RispExp::Symbol(s) =&gt; s.clone(),
            RispExp::Number(n) =&gt; n.to_string(),
            RispExp::List(list) =&gt; {
                let xs: Vec&lt;String&gt; = list.iter().map(|x| x.to_string()).collect();
                format!("({})", xs.join(","))
            }
            RispExp::Func(_) =&gt; "Function {}".to_string(),
            RispExp::Lambda(_) =&gt; "Lambda {}".to_string(),
        };

        write!(f, "{}", str)
    }
}

#[derive(Debug)]
enum RispErr {
    Reason(String),
}

#[derive(Clone)]
struct RispEnv&lt;'a&gt; {
    data: HashMap&lt;String, RispExp&gt;,
    outer: Option&lt;&amp;'a RispEnv&lt;'a&gt;&gt;,
}

/*
  Parse
*/

fn tokenize(expr: String) -&gt; Vec&lt;String&gt; {
    expr.replace("(", " ( ")
        .replace(")", " ) ")
        .split_whitespace()
        .map(|x| x.to_string())
        .collect()
}

fn parse(tokens: &amp;[String]) -&gt; Result&lt;(RispExp, &amp;[String]), RispErr&gt; {
    let (token, rest) = tokens
        .split_first()
        .ok_or_else(|| RispErr::Reason("could not get token".to_string()))?;
    match &amp;token[..] {
        "(" =&gt; read_seq(rest),
        ")" =&gt; Err(RispErr::Reason("unexpected `)`".to_string())),
        _ =&gt; Ok((parse_atom(token), rest)),
    }
}

fn read_seq(tokens: &amp;[String]) -&gt; Result&lt;(RispExp, &amp;[String]), RispErr&gt; {
    let mut res: Vec&lt;RispExp&gt; = vec![];
    let mut xs = tokens;
    loop {
        let (next_token, rest) = xs
            .split_first()
            .ok_or_else(|| RispErr::Reason("could not find closing `)`".to_string()))?;
        if next_token == ")" {
            return Ok((RispExp::List(res), rest)); // skip `)`, head to the token after
        }
        let (exp, new_xs) = parse(xs)?;
        res.push(exp);
        xs = new_xs;
    }
}

fn parse_atom(token: &amp;str) -&gt; RispExp {
    match token {
        "true" =&gt; RispExp::Bool(true),
        "false" =&gt; RispExp::Bool(false),
        _ =&gt; {
            let potential_float: Result&lt;f64, ParseFloatError&gt; = token.parse();
            match potential_float {
                Ok(v) =&gt; RispExp::Number(v),
                Err(_) =&gt; RispExp::Symbol(token.to_string()),
            }
        }
    }
}

/*
  Env
*/

macro_rules! ensure_tonicity {
    ($check_fn:expr) =&gt; {{
        |args: &amp;[RispExp]| -&gt; Result&lt;RispExp, RispErr&gt; {
            let floats = parse_list_of_floats(args)?;
            let first = floats
                .first()
                .ok_or_else(|| RispErr::Reason("expected at least one number".to_string()))?;
            let rest = &amp;floats[1..];
            fn f(prev: &amp;f64, xs: &amp;[f64]) -&gt; bool {
                match xs.first() {
                    Some(x) =&gt; $check_fn(prev, x) &amp;&amp; f(x, &amp;xs[1..]),
                    None =&gt; true,
                }
            }
            Ok(RispExp::Bool(f(first, rest)))
        }
    }};
}

fn default_env&lt;'a&gt;() -&gt; RispEnv&lt;'a&gt; {
    let mut data: HashMap&lt;String, RispExp&gt; = HashMap::new();
    data.insert(
        "+".to_string(),
        RispExp::Func(|args: &amp;[RispExp]| -&gt; Result&lt;RispExp, RispErr&gt; {
            let sum = parse_list_of_floats(args)?
                .iter()
                .fold(0.0, |sum, a| sum + a);

            Ok(RispExp::Number(sum))
        }),
    );
    data.insert(
        "-".to_string(),
        RispExp::Func(|args: &amp;[RispExp]| -&gt; Result&lt;RispExp, RispErr&gt; {
            let floats = parse_list_of_floats(args)?;
            let first = *floats
                .first()
                .ok_or_else(|| RispErr::Reason("expected at least one number".to_string()))?;
            let sum_of_rest = floats[1..].iter().fold(0.0, |sum, a| sum + a);

            Ok(RispExp::Number(first - sum_of_rest))
        }),
    );
    data.insert(
        "=".to_string(),
        RispExp::Func(ensure_tonicity!(
            |a: &amp;f64, b: &amp;f64| (a - b).abs() &lt; f64::EPSILON
        )),
    );
    data.insert(
        "&gt;".to_string(),
        RispExp::Func(ensure_tonicity!(|a, b| a &gt; b)),
    );
    data.insert(
        "&gt;=".to_string(),
        RispExp::Func(ensure_tonicity!(|a, b| a &gt;= b)),
    );
    data.insert(
        "&lt;".to_string(),
        RispExp::Func(ensure_tonicity!(|a, b| a &lt; b)),
    );
    data.insert(
        "&lt;=".to_string(),
        RispExp::Func(ensure_tonicity!(|a, b| a &lt;= b)),
    );

    RispEnv { data, outer: None }
}

fn parse_list_of_floats(args: &amp;[RispExp]) -&gt; Result&lt;Vec&lt;f64&gt;, RispErr&gt; {
    args.iter().map(|x| parse_single_float(x)).collect()
}

fn parse_single_float(exp: &amp;RispExp) -&gt; Result&lt;f64, RispErr&gt; {
    match exp {
        RispExp::Number(num) =&gt; Ok(*num),
        _ =&gt; Err(RispErr::Reason("expected a number".to_string())),
    }
}

